<?php

namespace App\Models;

use App\Models\Concerns\BelongsToOrganization;
use App\Models\Scopes\OrganizationScope;
use Database\Factories\DailyBriefFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * An internal-only "Daily Brief" (Step 2.5): one per client per calendar day, generated by
 * `App\Actions\AI\GenerateDailyBriefsAction` from `DiscoverTrendsAction`/`RecommendPostsAction`
 * output. Never surfaced to the client portal — only the Clients module's "Daily Briefs" tab.
 *
 * @property int $id
 * @property int $org_id
 * @property int $client_id
 * @property Carbon $brief_date
 * @property array<int, array<string, mixed>>|null $trends
 * @property array<int, array<string, mixed>>|null $ideas
 * @property Carbon|null $notified_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
#[Fillable(['org_id', 'client_id', 'brief_date', 'trends', 'ideas', 'notified_at'])]
class DailyBrief extends Model
{
    /** @use HasFactory<DailyBriefFactory> */
    use BelongsToOrganization, HasFactory;

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'brief_date' => 'date',
            'trends' => 'array',
            'ideas' => 'array',
            'notified_at' => 'datetime',
        ];
    }

    /**
     * @return BelongsTo<Organization, $this>
     */
    public function organization(): BelongsTo
    {
        return $this->belongsTo(Organization::class, 'org_id');
    }

    /**
     * @return BelongsTo<Client, $this>
     */
    public function client(): BelongsTo
    {
        // Step I-1.5: an archived (soft-deleted) client still owns its records.
        return $this->belongsTo(Client::class)->withTrashed()->withoutGlobalScope(OrganizationScope::class);
    }
}
